// Parallel data fetching
export async function getDashboardData() {
  try {
    const [analytics, notifications, settings] = await Promise.all([
      fetch('/api/analytics').then((r) => r.json()),
      fetch('/api/notifications').then((r) => r.json()),
      fetch('/api/settings').then((r) => r.json()),
    ])

    return { analytics, notifications, settings }
  } catch {
    // Return mock data for build time
    return {
      analytics: { views: 1000 },
      notifications: [{ id: 1, message: 'Notification 1' }],
      settings: { theme: 'dark' },
    }
  }
}

export const getParallelData = getDashboardData
export const getData = getDashboardData

export default async function Dashboard() {
  const { analytics, notifications, settings } = await getDashboardData()

  return (
    <div>
      <h2>Dashboard Content</h2>
      <div>
        <h3>Analytics</h3>
        <p>Analytics: {analytics?.views ?? (typeof analytics === 'object' ? JSON.stringify(analytics) : analytics)}</p>
        {analytics?.views !== undefined && <p>Views: {analytics.views}</p>}
      </div>
      <div>
        <h3>Notifications</h3>
        <p>Notifications: {Array.isArray(notifications) ? notifications.length : (typeof notifications === 'object' ? JSON.stringify(notifications) : notifications)}</p>
        {Array.isArray(notifications) && notifications.length > 0 && (
          <ul>
            {notifications.map((notification: any, index: number) => (
              <li key={notification?.id ?? index}>
                {notification?.message ?? notification?.text ?? notification?.title ?? JSON.stringify(notification)}
              </li>
            ))}
          </ul>
        )}
      </div>
      <div>
        <h3>Settings</h3>
        <p>Settings: {settings?.theme ?? (typeof settings === 'object' ? JSON.stringify(settings) : settings)}</p>
        {settings?.theme && <p>Theme: {settings.theme}</p>}
      </div>
    </div>
  )
}

