import { describe, it, expect, vi, beforeEach } from 'vitest'
import Dashboard, { getDashboardData } from './app/Dashboard'

describe('Dashboard', () => {
  beforeEach(() => {
    vi.restoreAllMocks()
  })

  it('fetches from all three endpoints in parallel', async () => {
    const promiseAllSpy = vi.spyOn(Promise, 'all')
    const fetchMock = vi.fn().mockImplementation((url: string) => {
      if (url === '/api/analytics') {
        return Promise.resolve({
          json: () => Promise.resolve({ views: 42 }),
        })
      }
      if (url === '/api/notifications') {
        return Promise.resolve({
          json: () => Promise.resolve([{ id: 1, message: 'Test notification' }]),
        })
      }
      if (url === '/api/settings') {
        return Promise.resolve({
          json: () => Promise.resolve({ theme: 'light' }),
        })
      }
      return Promise.reject(new Error(`Unexpected url ${url}`))
    })
    vi.stubGlobal('fetch', fetchMock)

    const jsx = await Dashboard()
    expect(promiseAllSpy).toHaveBeenCalled()
    expect(fetchMock).toHaveBeenCalledWith('/api/analytics')
    expect(fetchMock).toHaveBeenCalledWith('/api/notifications')
    expect(fetchMock).toHaveBeenCalledWith('/api/settings')
    expect(fetchMock).toHaveBeenCalledTimes(3)
  })

  it('handles fetch errors and returns mock data', async () => {
    vi.stubGlobal('fetch', vi.fn().mockRejectedValue(new Error('Network error')))
    const data = await getDashboardData()
    expect(data.analytics).toBeDefined()
    expect(data.notifications).toBeDefined()
    expect(data.settings).toBeDefined()
  })
})
